/* From Uiverse.io by Fadhilmagass  - Tags: minimalist, gradient, input, search, input, minimalist, gradient, search */
.__UIV_SCOPE__ .custom-container {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100%;
  min-height: 100%;
  padding: 20px;
  margin: 0;
  transition: background-color 0.3s;
}

.__UIV_SCOPE__ .custom-container.dark-mode {
  background-color: black;
}

.__UIV_SCOPE__ .custom-container.light-mode {
  background-color: white;
}

.__UIV_SCOPE__ .custom-search-bar {
  width: 100%;
  max-width: 600px;
  border-radius: 50px;
  padding: 10px 20px;
  display: flex;
  align-items: center;
  border: 2px solid;
  animation: rgb-outline 5s linear infinite;
  transition: background 0.3s, box-shadow 0.3s;
}

@keyframes rgb-outline {
  0% {
    border-color: rgb(255, 0, 0);
  }

  33% {
    border-color: rgb(0, 255, 0);
  }

  66% {
    border-color: rgb(0, 0, 255);
  }

  100% {
    border-color: rgb(255, 0, 0);
  }
}

.__UIV_SCOPE__ .custom-search-bar.dark-mode {
  background: linear-gradient(145deg, #333, #000);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.5);
}

.__UIV_SCOPE__ .custom-search-bar.light-mode {
  background: linear-gradient(145deg, #ddd, #fff);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}

.__UIV_SCOPE__ .custom-search-input {
  background: transparent;
  border: none;
  outline: none;
  width: 100%;
  padding: 10px;
  font-size: 16px;
  transition: color 0.3s;
}

.__UIV_SCOPE__ .custom-search-input.dark-mode {
  color: white;
}

.__UIV_SCOPE__ .custom-search-input.light-mode {
  color: black;
}

.__UIV_SCOPE__ .custom-search-input::placeholder {
  transition: color 0.3s;
}

.__UIV_SCOPE__ .custom-search-input::placeholder.dark-mode {
  color: #888;
}

.__UIV_SCOPE__ .custom-search-input::placeholder.light-mode {
  color: #aaa;
}

.__UIV_SCOPE__ .custom-search-icon,
.__UIV_SCOPE__ .custom-filter-icon {
  margin: 0 10px;
  transition: color 0.3s;
}

.__UIV_SCOPE__ .custom-search-icon.dark-mode,
.__UIV_SCOPE__ .custom-filter-icon.dark-mode {
  color: white;
}

.__UIV_SCOPE__ .custom-search-icon.light-mode,
.__UIV_SCOPE__ .custom-filter-icon.light-mode {
  color: black;
}

.__UIV_SCOPE__ .toggle-theme {
  position: absolute;
  top: 20px;
  right: 20px;
  padding: 10px;
  border: none;
  background-color: gray;
  color: white;
  border-radius: 5px;
  cursor: pointer;
}
